<script setup>
import { computed, ref } from 'vue'
import { Landmark, ShoppingBag, Undo2, WalletCards } from 'lucide-vue-next'
import BaseModal from '../components/BaseModal.vue'
import MetricCard from '../components/MetricCard.vue'
import { showToast } from '../utils.js'

const active=ref('orders'), keyword=ref(''), modal=ref(false), modalTitle=ref('交易详情')
const metrics=[['今日订单','428','↑ 18.2%',ShoppingBag,false],['实付金额','¥36,820','客单价 ¥86.03',WalletCards,false],['待审退款','3','最长等待 18 分钟',Undo2,true],['待结算','¥12,540','共 16 笔',Landmark,false]]
const orders=[['TLX2026071300821','林宇','同路洗车 · 精洗服务','¥128','¥30','¥98','14:32','已支付','success'],['TLX2026071300818','陈晓','川途营地 · 营位券','¥260','¥50','¥210','13:48','已核销','info'],['TLX2026071300806','周明','悦行维修 · 基础保养','¥399','¥0','¥399','12:05','待支付','warning']]
const shownOrders=computed(()=>orders.filter(row=>row.join(' ').toLowerCase().includes(keyword.value.toLowerCase())))
function switchTab(id){active.value=id;keyword.value=''} function open(title){modalTitle.value=title;modal.value=true} function action(text){modal.value=false;showToast(text)}
</script>

<template><div class="page"><div class="page-head"><div><h1>交易管理</h1><p>订单、退款、结算与核销撤销的一体化处理台</p></div><div class="head-actions"><button class="btn" @click="showToast('流水导出任务已创建（原型）')">导出流水</button><button class="btn primary" @click="showToast('交易数据已刷新')">刷新数据</button></div></div>
